const pts=[
  {p:[-0.100,0.148,0.100]},
  {p:[-0.100,0.148,0.021]},
  {p:[-0.100,0.148,0.021],hold:0.50},
  {p:[-0.100,0.148,0.100]}
];
let cur=start, rows=[];
for(const item of pts){
  const p=item.p;
  const d=Math.hypot(...p.map((v,i)=>v-cur[i]));
  const n=Math.max(1,Math.ceil(d/0.010));
  for(let k=1;k<=n;k++) rows.push([...p.map((v,i)=>cur[i]+(v-cur[i])*k/n),...q]);
  cur=p;
  const h=Math.round((item.hold||0)/.05);
